args.sparql:
SELECT ?film ?filmLabel ?dir ?dirLabel ?death WHERE {
  VALUES ?film { dbr:The_Fatal_Mistake <http://dbpedia.org/resource/The_Devil's_Hairpin> }
  ?film dbo:director ?dir .
  OPTIONAL { ?dir dbo:deathDate ?death . }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?dir rdfs:label ?dirLabel . FILTER(lang(?dirLabel) = 'en') }
}

SELECT ?film ?filmLabel ?dir ?dirLabel ?death WHERE {
  VALUES ?film { dbr:The_Fatal_Mistake <http://dbpedia.org/resource/The_Devil's_Hairpin> }
  ?film dbo:director ?dir .
  ?dir dbo:deathDate ?death .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?dir rdfs:label ?dirLabel . FILTER(lang(?dirLabel) = 'en') }
}
ORDER BY DESC(?death)
LIMIT 1

